using OptimizationXY.Charger.Models.Geometry;
using OptimizationXY.Charger.Models.Optimization.Recovery;
using OptimizationXY.Charger.Models.Optimization.Spindle;
using OptimizationXY.Charger.Models.Settings;

namespace OptimizationXY.Charger.Services.Optimization.Recovery;

/// <summary>
/// Metrics-only circular rotary-peel simulation for candidate search.
/// The same machine assumptions as the rendered peel are used: a fixed XY
/// spindle axis, circular rotation, fixed veneer thickness, and a fixed core.
/// No rotation command is generated by this class or by the application.
/// <para>
/// Used by the RecoveryOptimized direct search (works on the binned
/// spindle-axis field so hundreds of candidates are fast). Steps:
/// re-measure every cell's radius/angle around the candidate axis -> outer
/// radius = OuterRadiusPercentile of those radii -> peel radii from the outer
/// radius down to the core in veneer-thickness steps -> lay each revolution
/// end to end as a ribbon (length 2 pi r per turn) and cut it into sheets ->
/// a cell is wane on a revolution when the peel radius is more than
/// WaneToleranceMM beyond the wood there (severe beyond SevereWaneMM) ->
/// a full sheet is usable when its coverage and severe wane pass the PeelView
/// limits.
/// </para>
/// </summary>
public static class VeneerRecoveryMetricsEvaluator
{
    private const double MillimetersPerInch = 25.4;
    private const double TwoPi = 2.0 * Math.PI;

    /// <summary>
    /// Evaluates the recovery metrics for a given binned radius field and spindle movement.
    /// </summary>
    /// <param name="radiusField">The binned radius field points to evaluate.</param>
    /// <param name="peelSettings">The peel view settings.</param>
    /// <param name="usableSettings">The usable radius settings.</param>
    /// <param name="waneSettings">The wane settings.</param>
    /// <param name="recoverySettings">The recovery optimization settings.</param>
    /// <param name="movement">The optimized spindle movement.</param>
    /// <returns>The recovery search metrics.</returns>
    public static RecoverySearchMetrics Evaluate(
        IReadOnlyList<BinnedRadiusFieldPoint> radiusField,
        PeelViewSettings peelSettings,
        UsableRadiusSettings usableSettings,
        WaneSettings waneSettings,
        RecoveryOptimizationSettings recoverySettings,
        OptimizedSpindleMovement movement)
    {
        ArgumentNullException.ThrowIfNull(radiusField);
        ArgumentNullException.ThrowIfNull(peelSettings);
        ArgumentNullException.ThrowIfNull(usableSettings);
        ArgumentNullException.ThrowIfNull(waneSettings);
        ArgumentNullException.ThrowIfNull(recoverySettings);
        ArgumentNullException.ThrowIfNull(movement);

        List<BinnedRadiusFieldPoint> valid = [.. radiusField
            .Where(point =>
                point.Count > 0 &&
                double.IsFinite(point.ZBinMM) &&
                double.IsFinite(point.AngleBinDeg) &&
                double.IsFinite(point.MeanRadiusMM) &&
                point.MeanRadiusMM > 0.0)];

        if (valid.Count == 0)
            return Invalid("The binned radius field contains no valid surface cells.");

        int zCoverage = valid
            .Select(point => Math.Round(point.ZBinMM, 3))
            .Distinct()
            .Count();

        int angularCoverage = valid
            .Select(point => NormalizeAngle(point.AngleBinDeg))
            .Select(angle => Math.Round(angle, 3))
            .Distinct()
            .Count();

        if (zCoverage < recoverySettings.MinimumRecoverySearchZBins)
        {
            return Invalid(
                $"Recovery search needs at least {recoverySettings.MinimumRecoverySearchZBins} Z bins; received {zCoverage}.");
        }

        if (angularCoverage < recoverySettings.MinimumRecoverySearchAngularBins)
        {
            return Invalid(
                $"Recovery search needs at least {recoverySettings.MinimumRecoverySearchAngularBins} angular bins; received {angularCoverage}.");
        }

        double minZ = valid.Min(point => point.ZBinMM);
        double maxZ = valid.Max(point => point.ZBinMM);
        double zRange = Math.Max(0.000001, maxZ - minZ);

        var adjustedCells = new List<AdjustedSurfaceCell>(valid.Count);
        var adjustedRadii = new List<double>(valid.Count);

        foreach (BinnedRadiusFieldPoint point in valid)
        {
            double originalAngleRad =
                NormalizeAngle(point.AngleBinDeg) * Math.PI / 180.0;

            double surfaceX = point.MeanRadiusMM * Math.Cos(originalAngleRad);
            double surfaceY = point.MeanRadiusMM * Math.Sin(originalAngleRad);

            double t = Math.Clamp((point.ZBinMM - minZ) / zRange, 0.0, 1.0);
            double spindleX = movement.TailMoveXMM +
                (movement.HeadMoveXMM - movement.TailMoveXMM) * t;
            double spindleY = movement.TailMoveYMM +
                (movement.HeadMoveYMM - movement.TailMoveYMM) * t;

            double dx = surfaceX - spindleX;
            double dy = surfaceY - spindleY;
            double adjustedRadius = Math.Sqrt(dx * dx + dy * dy);

            if (!double.IsFinite(adjustedRadius) || adjustedRadius <= 0.0)
                continue;

            double adjustedAngle = Math.Atan2(dy, dx);
            if (adjustedAngle < 0.0)
                adjustedAngle += TwoPi;

            adjustedCells.Add(new AdjustedSurfaceCell(adjustedRadius, adjustedAngle));
            adjustedRadii.Add(adjustedRadius);
        }

        if (adjustedCells.Count == 0)
            return Invalid("No adjusted surface cells remained after applying the spindle axis.");

        double outerRadiusMM = Percentile(
            adjustedRadii,
            peelSettings.OuterRadiusPercentile);

        double coreRadiusMM =
            usableSettings.CoreDiameterInches * MillimetersPerInch / 2.0;

        if (!double.IsFinite(outerRadiusMM) || outerRadiusMM <= coreRadiusMM)
        {
            return Invalid(
                "The candidate outer radius is at or below the configured peel core radius.");
        }

        double veneerThicknessMM = usableSettings.VeneerThicknessMM;
        if (!double.IsFinite(veneerThicknessMM) || veneerThicknessMM <= 0.0)
            return Invalid("Veneer thickness must be a positive finite value.");

        List<double> peelRadii = BuildPeelRadii(
            outerRadiusMM,
            coreRadiusMM,
            veneerThicknessMM);

        if (peelRadii.Count == 0)
            return Invalid("The candidate contains no peel revolutions above the core.");

        double sheetLengthMM =
            Math.Max(1.0, peelSettings.VeneerMarkerSpacingInches) *
            MillimetersPerInch;

        double totalVeneerLengthMM = 0.0;
        double[] revolutionStarts = new double[peelRadii.Count];
        double[] revolutionWidths = new double[peelRadii.Count];

        for (int revolution = 0; revolution < peelRadii.Count; revolution++)
        {
            revolutionStarts[revolution] = totalVeneerLengthMM;
            revolutionWidths[revolution] = TwoPi * peelRadii[revolution];
            totalVeneerLengthMM += revolutionWidths[revolution];
        }

        int totalFullSheets = Math.Max(
            0,
            (int)Math.Floor(totalVeneerLengthMM / sheetLengthMM));

        if (totalFullSheets == 0)
        {
            return new RecoverySearchMetrics
            {
                IsValid = true,
                Revolutions = peelRadii.Count,
                OuterDiameterMM = outerRadiusMM * 2.0,
                CoreDiameterMM = coreRadiusMM * 2.0,
                TotalVeneerLengthMM = totalVeneerLengthMM
            };
        }

        long[] totalCellsBySheet = new long[totalFullSheets];
        long[] waneCellsBySheet = new long[totalFullSheets];
        long[] severeCellsBySheet = new long[totalFullSheets];

        long allCells = 0;
        long allWaneCells = 0;
        long allSevereCells = 0;

        for (int revolution = 0; revolution < peelRadii.Count; revolution++)
        {
            double peelRadiusMM = peelRadii[revolution];
            double revolutionStartMM = revolutionStarts[revolution];
            double revolutionWidthMM = revolutionWidths[revolution];

            foreach (AdjustedSurfaceCell cell in adjustedCells)
            {
                // Where along the unrolled ribbon this cell is on this revolution.
                double veneerDistanceMM = revolutionStartMM +
                    (cell.AngleRadians / TwoPi) * revolutionWidthMM;

                int sheetIndex = (int)Math.Floor(
                    veneerDistanceMM / sheetLengthMM);

                // The partial trailing sheet is not counted as a full sheet.
                if (sheetIndex < 0 || sheetIndex >= totalFullSheets)
                    continue;

                // Positive = the knife circle is outside the wood here (no veneer = wane).
                double missingWoodMM = peelRadiusMM - cell.RadiusMM;
                bool isWane = missingWoodMM > waneSettings.WaneToleranceMM;
                bool isSevere = missingWoodMM > waneSettings.SevereWaneMM;

                totalCellsBySheet[sheetIndex]++;
                allCells++;

                if (isWane)
                {
                    waneCellsBySheet[sheetIndex]++;
                    allWaneCells++;
                }

                if (isSevere)
                {
                    severeCellsBySheet[sheetIndex]++;
                    allSevereCells++;
                }
            }
        }

        int usableFullSheets = 0;
        double coverageSum = 0.0;

        for (int sheet = 0; sheet < totalFullSheets; sheet++)
        {
            long totalCells = totalCellsBySheet[sheet];
            double wanePercent = totalCells > 0
                ? 100.0 * waneCellsBySheet[sheet] / totalCells
                : 100.0;
            double severePercent = totalCells > 0
                ? 100.0 * severeCellsBySheet[sheet] / totalCells
                : 100.0;
            double coveragePercent = Math.Clamp(100.0 - wanePercent, 0.0, 100.0);

            coverageSum += coveragePercent;

            if (coveragePercent >= peelSettings.MinimumUsableSheetCoveragePercent &&
                severePercent <= peelSettings.MaximumUsableSheetSevereWanePercent)
            {
                usableFullSheets++;
            }
        }


        return new RecoverySearchMetrics
        {
            IsValid = true,
            Revolutions = peelRadii.Count,
            TotalFullSheets = totalFullSheets,
            UsableFullSheets = usableFullSheets,
            RejectedFullSheets = totalFullSheets - usableFullSheets,
            OuterDiameterMM = outerRadiusMM * 2.0,
            CoreDiameterMM = coreRadiusMM * 2.0,
            TotalVeneerLengthMM = totalVeneerLengthMM,
            UsableVeneerLengthMM = usableFullSheets * sheetLengthMM,
            TotalWaneAreaPercent = allCells > 0
                ? 100.0 * allWaneCells / allCells
                : 100.0,
            SevereWaneAreaPercent = allCells > 0
                ? 100.0 * allSevereCells / allCells
                : 100.0,
            AverageUsableCoveragePercent = totalFullSheets > 0
                ? coverageSum / totalFullSheets
                : 0.0
        };
    }

    /// <summary>
    /// Compares two recovery search metrics and determines if the candidate is better than the current.
    /// </summary>
    /// <param name="candidate">The candidate recovery search metrics to evaluate.</param>
    /// <param name="candidateMovementMM">The optimized spindle movement for the candidate.</param>
    /// <param name="current">The current best recovery search metrics.</param>
    /// <param name="currentMovementMM">The optimized spindle movement for the current best metrics.</param>
    /// <param name="preferLowerMovementOnExactTie">Indicates whether to prefer candidates with lower movement in the event of an exact tie.</param>
    /// <returns>True if the candidate is better than the current; otherwise, false.</returns>
    public static bool IsBetter(
        RecoverySearchMetrics candidate,
        double candidateMovementMM,
        RecoverySearchMetrics current,
        double currentMovementMM,
        bool preferLowerMovementOnExactTie)
    {
        if (!candidate.IsValid)
            return false;

        if (!current.IsValid)
            return true;

        if (candidate.UsableFullSheets != current.UsableFullSheets)
            return candidate.UsableFullSheets > current.UsableFullSheets;

        if (Math.Abs(candidate.UsableVeneerLengthMM - current.UsableVeneerLengthMM) > 0.001)
            return candidate.UsableVeneerLengthMM > current.UsableVeneerLengthMM;

        if (candidate.RejectedFullSheets != current.RejectedFullSheets)
            return candidate.RejectedFullSheets < current.RejectedFullSheets;

        if (Math.Abs(candidate.SevereWaneAreaPercent - current.SevereWaneAreaPercent) > 0.0001)
            return candidate.SevereWaneAreaPercent < current.SevereWaneAreaPercent;

        if (Math.Abs(candidate.TotalWaneAreaPercent - current.TotalWaneAreaPercent) > 0.0001)
            return candidate.TotalWaneAreaPercent < current.TotalWaneAreaPercent;

        if (Math.Abs(candidate.AverageUsableCoveragePercent - current.AverageUsableCoveragePercent) > 0.0001)
            return candidate.AverageUsableCoveragePercent > current.AverageUsableCoveragePercent;

        return preferLowerMovementOnExactTie &&
               candidateMovementMM < currentMovementMM;
    }

    /// <summary>
    /// Creates an invalid recovery search metrics instance with the specified reason.
    /// </summary>
    /// <param name="reason">The reason why the recovery search metrics are considered invalid.</param>
    /// <returns>An invalid recovery search metrics instance.</returns>
    private static RecoverySearchMetrics Invalid(string reason) =>
        new()
        {
            IsValid = false,
            InvalidReason = reason
        };

    /// <summary>
    /// Builds a list of peel radii starting from the outer radius down to the core radius, decrementing by the veneer
    /// thickness for each revolution.
    /// </summary>
    /// <param name="outerRadiusMM">The outer radius in millimeters.</param>
    /// <param name="coreRadiusMM">The core radius in millimeters.</param>
    /// <param name="veneerThicknessMM">The veneer thickness in millimeters.</param>
    /// <returns>A list of peel radii from the outer radius down to the core radius.</returns>
    private static List<double> BuildPeelRadii(
        double outerRadiusMM,
        double coreRadiusMM,
        double veneerThicknessMM)
    {
        var radii = new List<double>();
        for (double radius = outerRadiusMM;
             radius > coreRadiusMM;
             radius -= veneerThicknessMM)
        {
            radii.Add(radius);
        }

        return radii;
    }

    /// <summary>
    /// Normalizes an angle in degrees to the range [0, 360).
    /// </summary>
    /// <param name="angleDegrees">The angle in degrees to normalize.</param>
    /// <returns>The normalized angle in the range [0, 360).</returns>
    private static double NormalizeAngle(double angleDegrees)
    {
        angleDegrees %= 360.0;
        if (angleDegrees < 0.0)
            angleDegrees += 360.0;
        return angleDegrees;
    }

    /// <summary>
    /// Calculates the specified percentile of a list of double values. The percentile should be in the range [0, 1],
    /// where 0 represents the minimum value and 1 represents the maximum value. The method sorts the
    /// values and interpolates between them to find the desired percentile.
    /// </summary>
    /// <param name="values">The list of double values.</param>
    /// <param name="percentile">The desired percentile in the range [0, 1].</param>
    /// <returns>The value at the specified percentile.</returns>
    private static double Percentile(
        List<double> values,
        double percentile)
    {
        if (values.Count == 0)
            return 0.0;

        percentile = Math.Clamp(percentile, 0.0, 1.0);
        double[] sorted = [.. values.OrderBy(value => value)];
        double position = percentile * (sorted.Length - 1);
        int lower = (int)Math.Floor(position);
        int upper = (int)Math.Ceiling(position);

        if (lower == upper)
            return sorted[lower];

        double weight = position - lower;
        return sorted[lower] * (1.0 - weight) + sorted[upper] * weight;
    }

    /// <summary>
    /// Represents an adjusted surface cell with a radius and angle in radians, used for recovery metrics evaluation.
    /// </summary>
    /// <param name="RadiusMM">The radius of the surface cell in millimeters.</param>
    /// <param name="AngleRadians">The angle of the surface cell in radians.</param>
    private readonly record struct AdjustedSurfaceCell(
        double RadiusMM,
        double AngleRadians);
}
